1	import { useQuery } from "@tanstack/react-query";
2	import { Link, navigate, useQueryParams } from "raviger";
3	import { useState } from "react";
4	import { useTranslation } from "react-i18next";
5	
6	import Loading from "@/components/Common/Loading";
7	import PageTitle from "@/components/Common/PageTitle";
8	import BecknFlow from "@/components/Resource/beckn/BecknFlow";
9	import { Badge } from "@/components/ui/badge";
10	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
11	import {
12	  Select,
13	  SelectContent,
14	  SelectItem,
15	  SelectTrigger,
16	  SelectValue,
17	} from "@/components/ui/select";
18	import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
19	
20	import query from "@/Utils/request/query";
21	import {
22	  becknPatientFrom,
23	  HEALTH_SERVICE_TYPES,
24	} from "@/types/beckn/becknModels";
25	import {
26	  getResourceRequestCategoryEnum,
27	  ResourceRequestListRead,
28	  ResourceRequestRead,
29	  ResourceRequestStatus,
30	} from "@/types/resourceRequest/resourceRequest";
31	import resourceRequestApi from "@/types/resourceRequest/resourceRequestApi";
32	
33	// Health service types the coordinator can book an appointment for.
34	
35	interface CcnConsoleProps {
36	  facilityId: string;
37	  resourceId?: string;
38	}
39	
40	/** Which side of the referral this facility is on. */
41	type CcnTab = "incoming" | "outgoing";
42	
43	/**
44	 * A request is Incoming when its origin facility is also its assigned facility.
45	 * Everything else in the assigned-to-self result set is Outgoing.
46	 */
47	function isIncomingRequest(request: ResourceRequestListRead): boolean {
48	  return (
49	    !!request.origin_facility?.id &&
50	    request.origin_facility.id === request.assigned_facility?.id
51	  );
52	}
53	
54	/**
55	 * Care-Coordinator console: ResourceRequests on the left, and on selection the
56	 * request detail on the right.
57	 *
58	 * A single fetch (`assigned_facility=self`) returns every request routed to this
59	 * facility; the two tabs are then split client-side, avoiding a second query for
60	 * a filter the coordinator can derive itself. **Incoming** is the working tab —
61	 * requests whose origin facility is also the assigned facility, i.e. raised and
62	 * fulfilled here; the origin facility places and confirms the referral itself
63	 * (it is the BAP consumer), so requests reach this console already `approved` and
64	 * the desk can run the Beckn appointment-booking flow. **Outgoing** is every
65	 * other request (raised elsewhere, routed here) and is read-only, since booking
66	 * is the originating desk's job. The FE never speaks Beckn directly — it calls
67	 * Care BE's BAP REST endpoints (see BecknFlow / the hook).
68	 */
69	export default function CcnConsole({
70	  facilityId,
71	  resourceId,
72	}: CcnConsoleProps) {
73	  const { t } = useTranslation();
74	  // Kept in the URL so the tab survives selecting a request (which navigates)
75	  // and stays shareable. Anything unrecognised falls back to incoming.
76	  const [{ tab }] = useQueryParams<{ tab?: string }>();
77	  const activeTab: CcnTab = tab === "outgoing" ? "outgoing" : "incoming";
78	  const isOutgoing = activeTab === "outgoing";
79	
80	  // One fetch for both tabs — everything assigned to this facility.
81	  const { data: list, isLoading: listLoading } = useQuery({
82	    queryKey: ["ccn-resource-list", facilityId],
83	    queryFn: query(resourceRequestApi.list, {
84	      queryParams: { limit: 100, origin_facility: facilityId },
85	    }),
86	  });
87	
88	  // Incoming = origin facility is the assigned facility; Outgoing = the rest.
89	  const requests = (list?.results ?? []).filter((item) =>
90	    isOutgoing ? !isIncomingRequest(item) : isIncomingRequest(item),
91	  );
92	
93	  // A request only exists in one of the two lists, so switching tabs drops the
94	  // current selection rather than leaving the detail pane out of step.
95	  const selectTab = (next: CcnTab) =>
96	    navigate(
97	      `/facility/${facilityId}/ccn${next === "outgoing" ? "?tab=outgoing" : ""}`,
98	    );
99	
100	  return (
101	    <div className="p-4">
102	      <PageTitle title={t("cc_console")} />
103	      <div className="flex h-[calc(100vh-9rem)] overflow-hidden rounded-lg border">
104	        <aside className="flex w-80 shrink-0 flex-col overflow-hidden border-r bg-gray-50">
105	          <div className="shrink-0 border-b p-2">
106	            <Tabs value={activeTab}>
107	              <TabsList className="inline-flex h-8 w-full bg-transparent p-0">
108	                <TabsTrigger
109	                  value="incoming"
110	                  className="w-full data-[state=active]:bg-primary/10 data-[state=active]:text-primary"
111	                  onClick={() => selectTab("incoming")}
112	                >
113	                  {t("incoming")}
114	                </TabsTrigger>
115	                <TabsTrigger
116	                  value="outgoing"
117	                  className="w-full data-[state=active]:bg-primary/10 data-[state=active]:text-primary"
118	                  onClick={() => selectTab("outgoing")}
119	                >
120	                  {t("outgoing")}
121	                </TabsTrigger>
122	              </TabsList>
123	            </Tabs>
124	          </div>
125	
126	          <div className="flex-1 overflow-y-auto">
127	            {listLoading ? (
128	              <div className="p-4 text-sm text-gray-500">{t("loading")}</div>
129	            ) : requests.length === 0 ? (
130	              <div className="p-4 text-sm text-gray-500">
131	                {isOutgoing
132	                  ? t("ccn_no_outgoing_requests")
133	                  : t("ccn_no_incoming_requests")}
134	              </div>
135	            ) : (
136	              <ul className="divide-y">
137	                {requests.map((item) => {
138	                  const active = item.id === resourceId;
139	                  return (
140	                    <li key={item.id}>
141	                      <Link
142	                        href={`/facility/${facilityId}/ccn/${item.id}${
143	                          isOutgoing ? "?tab=outgoing" : ""
144	                        }`}
145	                        className={[
146	                          "block px-4 py-3 hover:bg-white",
147	                          active
148	                            ? "border-l-2 border-primary-600 bg-white"
149	                            : "",
150	                        ].join(" ")}
151	                      >
152	                        <div className="flex items-center justify-between gap-2">
153	                          <span className="truncate text-sm font-medium">
154	                            {item.title || t("ccn_untitled_request")}
155	                          </span>
156	                          <Badge
157	                            variant="secondary"
158	                            className="shrink-0 text-[10px]"
159	                          >
160	                            {item.status}
161	                          </Badge>
162	                        </div>
163	                        <p className="mt-1 truncate text-xs text-gray-500">
164	                          {item.origin_facility?.name ?? ""}
165	                        </p>
166	                      </Link>
167	                    </li>
168	                  );
169	                })}
170	              </ul>
171	            )}
172	          </div>
173	        </aside>
174	
175	        <main className="flex-1 overflow-y-auto p-4">
176	          {resourceId ? (
177	            <ResourceDetail
178	              facilityId={facilityId}
179	              resourceId={resourceId}
180	              readOnly={isOutgoing}
181	            />
182	          ) : (
183	            <div className="flex h-full items-center justify-center text-sm text-gray-500">
184	              {t("ccn_select_request_to_begin")}
185	            </div>
186	          )}
187	        </main>
188	      </div>
189	    </div>
190	  );
191	}
192	
193	function ResourceDetail({
194	  facilityId,
195	  resourceId,
196	  readOnly,
197	}: {
198	  facilityId: string;
199	  resourceId: string;
200	  readOnly: boolean;
201	}) {
202	  const { t } = useTranslation();
203	  const { data: resource, isLoading } = useQuery({
204	    queryKey: ["ccn-resource", resourceId],
205	    queryFn: query(resourceRequestApi.get, {
206	      pathParams: { resourceRequestId: resourceId },
207	    }),
208	  });
209	
210	  if (isLoading || !resource) {
211	    return <Loading />;
212	  }
213	
214	  const isApproved = resource.status === ResourceRequestStatus.APPROVED;
215	
216	  return (
217	    <div className="mx-auto max-w-2xl space-y-4">
218	      <Card>
219	        <CardHeader>
220	          <CardTitle className="flex items-center justify-between gap-2">
221	            <span>{resource.title || t("ccn_untitled_request")}</span>
222	            <Badge variant="secondary">
223	              {t(`resource_request_status__${resource.status}`)}
224	            </Badge>
225	          </CardTitle>
226	        </CardHeader>
227	        <CardContent className="space-y-2 text-sm">
228	          <DetailRow
229	            label={t("patient")}
230	            value={resource.related_patient?.name ?? "—"}
231	          />
232	          <DetailRow
233	            label={t("category")}
234	            value={t(
235	              `resource_request_category__${getResourceRequestCategoryEnum(
236	                resource.category,
237	              )}`,
238	            )}
239	          />
240	          <DetailRow
241	            label={t("origin_facility")}
242	            value={resource.origin_facility?.name ?? "—"}
243	          />
244	          {resource.reason ? (
245	            <DetailRow label={t("reason")} value={resource.reason} />
246	          ) : null}
247	        </CardContent>
248	      </Card>
249	
250	      {readOnly ? (
251	        <p className="text-sm text-gray-500">{t("ccn_outgoing_read_only")}</p>
252	      ) : isApproved ? (
253	        <AppointmentBooking facilityId={facilityId} resource={resource} />
254	      ) : (
255	        <p className="text-sm text-gray-500">
256	          {t("ccn_booking_available_once_approved")}
257	        </p>
258	      )}
259	    </div>
260	  );
261	}
262	
263	/**
264	 * Appointment booking for an approved request: the coordinator picks a health
265	 * service type, then runs the Beckn appointment flow (discover → select → slot
266	 * → confirm).
267	 */
268	function AppointmentBooking({
269	  facilityId,
270	  resource,
271	}: {
272	  facilityId: string;
273	  resource: ResourceRequestRead;
274	}) {
275	  const { t } = useTranslation();
276	  const [healthServiceType, setHealthServiceType] = useState<string>(
277	    HEALTH_SERVICE_TYPES[0].value,
278	  );
279	
280	  return (
281	    <div className="space-y-3">
282	      <div className="space-y-1">
283	        <p className="text-sm font-medium">{t("ccn_service_type")}</p>
284	        <Select value={healthServiceType} onValueChange={setHealthServiceType}>
285	          <SelectTrigger className="w-full">
286	            <SelectValue placeholder={t("ccn_select_service_type")} />
287	          </SelectTrigger>
288	          <SelectContent>
289	            {HEALTH_SERVICE_TYPES.map((option) => (
290	              <SelectItem key={option.value} value={option.value}>
291	                {t(option.labelKey)}
292	              </SelectItem>
293	            ))}
294	          </SelectContent>
295	        </Select>
296	      </div>
297	
298	      <BecknFlow
299	        serviceType="appointment"
300	        facilityId={facilityId}
301	        patient={becknPatientFrom(resource.related_patient)}
302	        discover={{ healthServiceType }}
303	        // coordinationRef links the booking to the originating referral. The RR
304	        // record does not currently expose the Beckn coordinationId; wire it
305	        // here once the BE surfaces it.
306	        coordinationRef={undefined}
307	      />
308	    </div>
309	  );
310	}
311	
312	function DetailRow({ label, value }: { label: string; value: string }) {
313	  return (
314	    <div className="flex justify-between gap-4 border-b py-2 last:border-b-0">
315	      <span className="text-gray-500">{label}</span>
316	      <span className="text-right font-medium">{value}</span>
317	    </div>
318	  );
319	}
