1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { useTranslation } from "react-i18next";
3	
4	import CareIcon from "@/CAREUI/icons/CareIcon";
5	
6	import CatalogPicker from "@/components/Resource/beckn/CatalogPicker";
7	import ConfirmDialog, {
8	  ConfirmSummaryRow,
9	} from "@/components/Resource/beckn/ConfirmDialog";
10	import SlotPicker from "@/components/Resource/beckn/SlotPicker";
11	import { Button } from "@/components/ui/button";
12	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
13	
14	import { GENDER_TYPES } from "@/common/constants";
15	
16	import { formatDateTime } from "@/Utils/utils";
17	import { useBecknTransaction } from "@/hooks/useBecknTransaction";
18	import {
19	  BecknPatient,
20	  BecknServiceType,
21	  BecknSlot,
22	  CatalogOption,
23	  availabilityForOption,
24	  buildConfirmBody,
25	  buildDiscoverBody,
26	  buildInitBody,
27	  buildSelectBody,
28	  healthServiceTypeLabel,
29	} from "@/types/beckn/becknModels";
30	
31	interface BecknFlowProps {
32	  serviceType: BecknServiceType;
33	  facilityId: string;
34	  patient?: BecknPatient;
35	  discover: { textSearch?: string; healthServiceType?: string };
36	  /** Consultation only: resource-request title → `contract.descriptor.name`. */
37	  title?: string;
38	  /** Appointment only: link the originating referral. */
39	  coordinationRef?: string;
40	  /** Consultation (RR form): kick off discover as soon as the flow mounts. */
41	  autoStart?: boolean;
42	  onConfirmed?: (resourceRequestId?: string) => void;
43	}
44	
45	/**
46	 * Reusable Beckn orchestrator over the Care BAP.
47	 *
48	 * - `consultation`: pick a coordinator → Submit fires `init` (full
49	 *   ServiceCoordination contract), which mints the referral and creates the
50	 *   ResourceRequest → confirmation popup → `confirm` (carrying the contract id
51	 *   minted at init) finalises it. No slots.
52	 * - `appointment`: pick a provider → `select` → choose a slot → confirm popup →
53	 *   `confirm` books a TokenBooking (linked to the referral via coordinationRef).
54	 *
55	 * Both flows are driven by the origin facility as the BAP consumer: it places
56	 * the order and therefore fires `confirm` itself.
57	 */
58	export default function BecknFlow({
59	  serviceType,
60	  facilityId,
61	  patient,
62	  discover,
63	  title,
64	  coordinationRef,
65	  autoStart,
66	  onConfirmed,
67	}: BecknFlowProps) {
68	  const { t } = useTranslation();
69	  const flow = useBecknTransaction();
70	  const { act, transactionId, phase } = flow;
71	  const healthServiceType = discover.healthServiceType;
72	  const isConsultation = serviceType === "consultation";
73	
74	  const [option, setOption] = useState<CatalogOption>();
75	  const [slot, setSlot] = useState<BecknSlot>();
76	  const [slotKey, setSlotKey] = useState<string>();
77	  const [confirmOpen, setConfirmOpen] = useState(false);
78	  // Consultation: FE-generated coordination id, created once at init and reused
79	  // unchanged at confirm.
80	  const [coordinationId, setCoordinationId] = useState<string>();
81	
82	  const startDiscover = useCallback(() => {
83	    void act("discover", buildDiscoverBody({ serviceType, ...discover }));
84	  }, [act, serviceType, discover]);
85	
86	  const startedRef = useRef(false);
87	  useEffect(() => {
88	    if (autoStart && !startedRef.current && !transactionId) {
89	      startedRef.current = true;
90	      startDiscover();
91	    }
92	  }, [autoStart, transactionId, startDiscover]);
93	
94	  // Consultation Submit → init; appointment Submit → select.
95	  const doSubmit = useCallback(() => {
96	    if (!option || !transactionId) return;
97	    if (isConsultation) {
98	      const newCoordinationId = crypto.randomUUID();
99	      setCoordinationId(newCoordinationId);
100	      void act(
101	        "init",
102	        buildInitBody({
103	          transactionId,
104	          option,
105	          coordinationId: newCoordinationId,
106	          patient,
107	          facilityId,
108	          title,
109	        }),
110	      );
111	      return;
112	    }
113	    void act(
114	      "select",
115	      buildSelectBody({
116	        serviceType,
117	        transactionId,
118	        option,
119	        healthServiceType,
120	        availability: availabilityForOption(flow.slices["on_discover"], option),
121	      }),
122	    );
123	  }, [
124	    act,
125	    option,
126	    transactionId,
127	    isConsultation,
128	    serviceType,
129	    patient,
130	    facilityId,
131	    title,
132	    healthServiceType,
133	    flow.slices,
134	  ]);
135	
136	  const doConfirm = useCallback(() => {
137	    if (!option || !transactionId) return;
138	    setConfirmOpen(false);
139	    void act(
140	      "confirm",
141	      buildConfirmBody({
142	        serviceType,
143	        transactionId,
144	        option,
145	        patient,
146	        facilityId,
147	        slot,
148	        healthServiceType,
149	        coordinationRef,
150	        contractId: flow.initResult.contractId,
151	        coordinationId,
152	      }),
153	    );
154	  }, [
155	    act,
156	    option,
157	    transactionId,
158	    serviceType,
159	    patient,
160	    facilityId,
161	    slot,
162	    healthServiceType,
163	    coordinationRef,
164	    flow.initResult.contractId,
165	    coordinationId,
166	  ]);
167	
168	  // Both flows terminate at ON_CONFIRM: the origin facility confirms its own
169	  // referral (the BAP consumer places the order), and the appointment booking
170	  // is likewise finalised by confirm.
171	  const done = phase === "confirmed";
172	
173	  const confirmedRef = useRef(false);
174	  useEffect(() => {
175	    if (done && !confirmedRef.current) {
176	      confirmedRef.current = true;
177	      onConfirmed?.(flow.resourceRequestId);
178	    }
179	  }, [done, flow.resourceRequestId, onConfirmed]);
180	
181	  const startOver = useCallback(() => {
182	    startedRef.current = false;
183	    confirmedRef.current = false;
184	    setOption(undefined);
185	    setSlot(undefined);
186	    setSlotKey(undefined);
187	    setConfirmOpen(false);
188	    setCoordinationId(undefined);
189	    flow.reset();
190	  }, [flow]);
191	
192	  // A Beckn action is "busy" from the moment we fire it until its `on_*`
193	  // callback arrives (POST in flight → polling). Driving the UI off this — rather
194	  // than the raw status — means the gaps between submit and callback show a
195	  // loader instead of a stale interactive state.
196	  const busy = flow.acting || !!flow.awaiting;
197	  const showPicker = !busy && phase === "discovered";
198	  const showSlots = !busy && phase === "selected" && !isConsultation;
199	  // Consultation: `init` mints the referral, then the origin confirms it.
200	  const showReferralConfirm =
201	    !busy && isConsultation && phase === "initialized";
202	
203	  const waitingMessage = (() => {
204	    switch (flow.awaiting) {
205	      case "discover":
206	        return t("beckn_searching_providers");
207	      case "select":
208	        return t("beckn_loading_slots");
209	      case "init":
210	        return t("beckn_submitting_referral");
211	      case "confirm":
212	        return isConsultation
213	          ? t("beckn_confirming_referral")
214	          : t("beckn_booking_appointment");
215	      default:
216	        return t("beckn_working");
217	    }
218	  })();
219	
220	  // The popup is the last checkpoint before the order is placed on the network,
221	  // so it carries enough to verify *who* is being referred and *what* is being
222	  // committed to. Optional rows are dropped rather than rendered as dashes.
223	  const genderLabel = GENDER_TYPES.find((g) => g.id === patient?.gender)?.text;
224	  const serviceTypeLabel = healthServiceTypeLabel(healthServiceType);
225	  const referralId = flow.initResult.contractId;
226	
227	  const confirmSummary: ConfirmSummaryRow[] = [
228	    { label: t("patient"), value: patient?.name ?? "—" },
229	    ...(genderLabel ? [{ label: t("sex"), value: genderLabel }] : []),
230	    ...(patient?.dateOfBirth
231	      ? [
232	          {
233	            label: t("date_of_birth"),
234	            value: formatDateTime(patient.dateOfBirth),
235	          },
236	        ]
237	      : []),
238	    ...(patient?.abha
239	      ? [{ label: t("patient_id_abha"), value: patient.abha }]
240	      : []),
241	    ...(isConsultation && title
242	      ? [{ label: t("request_title"), value: title }]
243	      : []),
244	    ...(serviceTypeLabel
245	      ? [{ label: t("ccn_service_type"), value: serviceTypeLabel }]
246	      : []),
247	    {
248	      label: isConsultation
249	        ? t("ccn_coordination_desk")
250	        : t("beckn_provider_offer"),
251	      value: option?.label ?? "—",
252	    },
253	    ...(isConsultation
254	      ? []
255	      : [{ label: t("beckn_slot"), value: slot?.label ?? "—" }]),
256	    // Minted by the BPP at init — proof the referral exists and names what
257	    // confirm is about to finalise.
258	    ...(isConsultation && referralId
259	      ? [{ label: t("ccn_referral_id"), value: referralId }]
260	      : []),
261	  ];
262	
263	  return (
264	    <Card>
265	      <CardHeader>
266	        <CardTitle className="text-base">
267	          {serviceType === "appointment"
268	            ? t("book_appointment")
269	            : t("beckn_referral_booking")}
270	        </CardTitle>
271	      </CardHeader>
272	
273	      <CardContent className="space-y-4">
274	        {done ? (
275	          <div className="rounded-md border border-green-200 bg-green-50 p-3 text-sm text-green-800">
276	            <p className="font-medium">
277	              {serviceType === "appointment"
278	                ? t("beckn_appointment_booked")
279	                : t("beckn_referral_created")}
280	            </p>
281	            {flow.resourceRequestId ? (
282	              <p className="mt-1 text-xs">
283	                {t("beckn_resource_request_id", {
284	                  id: flow.resourceRequestId,
285	                })}
286	              </p>
287	            ) : null}
288	          </div>
289	        ) : phase === "error" ? (
290	          <>
291	            <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700">
292	              {flow.error ?? t("something_went_wrong")}
293	            </div>
294	            <Button variant="outline" onClick={startOver}>
295	              {t("beckn_start_over")}
296	            </Button>
297	          </>
298	        ) : busy ? (
299	          <StatusLine text={waitingMessage} />
300	        ) : phase === "idle" ? (
301	          <Button variant="primary" onClick={startDiscover}>
302	            {t("beckn_find_providers")}
303	          </Button>
304	        ) : showPicker ? (
305	          <div className="space-y-3">
306	            <CatalogPicker
307	              options={flow.catalog}
308	              value={option?.key}
309	              onChange={setOption}
310	            />
311	            <Button variant="primary" disabled={!option} onClick={doSubmit}>
312	              {isConsultation ? t("submit") : t("beckn_select_provider")}
313	            </Button>
314	          </div>
315	        ) : showSlots ? (
316	          <div className="space-y-3">
317	            <p className="text-sm font-medium">{t("beckn_choose_slot")}</p>
318	            <SlotPicker
319	              slots={flow.slots}
320	              value={slotKey}
321	              onChange={(s, key) => {
322	                setSlot(s);
323	                setSlotKey(key);
324	              }}
325	            />
326	            <Button
327	              variant="primary"
328	              disabled={!slot}
329	              onClick={() => setConfirmOpen(true)}
330	            >
331	              {t("beckn_confirm_booking")}
332	            </Button>
333	          </div>
334	        ) : showReferralConfirm ? (
335	          <Button variant="primary" onClick={() => setConfirmOpen(true)}>
336	            {t("ccn_confirm_referral")}
337	          </Button>
