1	import { useQuery, useQueryClient } from "@tanstack/react-query";
2	import { t } from "i18next";
3	import { useCallback, useEffect, useMemo, useState } from "react";
4	
5	import query, { callApi } from "@/Utils/request/query";
6	import becknApi from "@/types/beckn/becknApi";
7	import {
8	  BecknActionName,
9	  BecknActionResult,
10	  BecknInitResult,
11	  BecknSlice,
12	  BecknSlot,
13	  BecknTxnStatus,
14	  CatalogOption,
15	  extractInitResult,
16	  extractOffers,
17	  extractSlots,
18	  isTerminalStatus,
19	  sliceActionFor,
20	} from "@/types/beckn/becknModels";
21	
22	export type BecknPhase =
23	  | "idle"
24	  | "discovering"
25	  | "discovered"
26	  | "selecting"
27	  | "selected"
28	  | "initializing"
29	  | "initialized"
30	  | "confirming"
31	  | "confirmed"
32	  | "error";
33	
34	function phaseFor(status: string | undefined): BecknPhase {
35	  switch (status) {
36	    case undefined:
37	      return "idle";
38	    case "DISCOVER":
39	      return "discovering";
40	    case "ON_DISCOVER":
41	      return "discovered";
42	    case "SELECT":
43	      return "selecting";
44	    case "ON_SELECT":
45	      return "selected";
46	    case "INIT":
47	      return "initializing";
48	    case "ON_INIT":
49	      return "initialized";
50	    case "CONFIRM":
51	      return "confirming";
52	    case "ON_CONFIRM":
53	      return "confirmed";
54	    case "NACK":
55	    case "ERROR":
56	      return "error";
57	    default:
58	      return "idle";
59	  }
60	}
61	
62	const POLL_MS = 1500;
63	const SLICE_POLL_MS = 1200;
64	
65	/**
66	 * Drives one Beckn transaction end-to-end against the Care BAP REST endpoints.
67	 *
68	 * `act(name, body)` fires an action (discover starts the txn and captures its
69	 * `transactionId`) and marks that action's `on_*` callback as *awaited*. The
70	 * status record is polled every ~1.5s **only while a callback is awaited**; the
71	 * moment the matching `ON_*` arrives it's the FE's turn, so polling pauses until
72	 * the next action fires. When the awaited `ON_*` lands, its slice is auto-fetched
73	 * and cached by action so earlier slices (e.g. the catalog) stay available.
74	 * Polling also stops on `NACK` / `ERROR`.
75	 */
76	export function useBecknTransaction() {
77	  const qc = useQueryClient();
78	  const [transactionId, setTransactionId] = useState<string>();
79	  const [slices, setSlices] = useState<Record<string, BecknSlice>>({});
80	  const [error, setError] = useState<string>();
81	  const [acting, setActing] = useState(false);
82	  // The action whose `on_*` callback we're waiting for; null when it's the FE's
83	  // turn (an `ON_*` was received) or the flow is at rest. Drives the poller.
84	  const [awaiting, setAwaiting] = useState<BecknActionName | null>(null);
85	
86	  const statusQuery = useQuery<BecknTxnStatus>({
87	    queryKey: ["beckn", "status", transactionId],
88	    queryFn: query(becknApi.status, {
89	      pathParams: { transactionId: transactionId as string },
90	    }),
91	    enabled: !!transactionId,
92	    refetchInterval: awaiting ? POLL_MS : false,
93	  });
94	
95	  const status = statusQuery.data?.status;
96	  const sliceAction = sliceActionFor(status);
97	
98	  const sliceQuery = useQuery<BecknSlice>({
99	    queryKey: ["beckn", "slice", transactionId, sliceAction],
100	    queryFn: query(becknApi.slice, {
101	      pathParams: { transactionId: transactionId as string },
102	      queryParams: { action: sliceAction as string },
103	    }),
104	    enabled: !!transactionId && !!sliceAction,
105	    refetchInterval: (q) => (q.state.data?.ready ? false : SLICE_POLL_MS),
106	  });
107	
108	  // Stop polling once the awaited callback (matching `ON_*`) or a terminal error
109	  // arrives — it's now the FE's turn (or the flow has failed).
110	  useEffect(() => {
111	    if (!awaiting) return;
112	    const expected = `ON_${awaiting.toUpperCase()}`;
113	    if (status === expected || status === "NACK" || status === "ERROR") {
114	      setAwaiting(null);
115	    }
116	  }, [status, awaiting]);
117	
118	  // Cache each ON_* slice once it is ready so the catalog survives later phases.
119	  useEffect(() => {
120	    const data = sliceQuery.data;
121	    if (data?.ready && sliceAction) {
122	      setSlices((prev) =>
123	        prev[sliceAction] ? prev : { ...prev, [sliceAction]: data },
124	      );
125	    }
126	  }, [sliceQuery.data, sliceAction]);
127	
128	  useEffect(() => {
129	    if (status === "NACK" || status === "ERROR") {
130	      setError((p) => p ?? t("beckn_request_failed"));
131	    }
132	  }, [status]);
133	
134	  const act = useCallback(
135	    async (
136	      name: BecknActionName,
137	      body: Record<string, unknown>,
138	    ): Promise<BecknActionResult> => {
139	      setError(undefined);
140	      setActing(true);
141	      // Expect an `on_<name>` callback → (re)start the poller.
142	      setAwaiting(name);
143	      try {
144	        const res = await callApi(becknApi.action, {
145	          pathParams: { action: name },
146	          body,
147	        });
148	        if (name === "discover") {
149	          setTransactionId(res.transactionId);
150	        }
151	        if (res.result === "nack" || res.result === "error") {
152	          setError(t("beckn_request_failed"));
153	          setAwaiting(null);
154	        } else if (res.result === "skipped") {
155	          setError(t("beckn_network_not_configured"));
156	          setAwaiting(null);
157	        }
158	        const tid = res.transactionId ?? transactionId;
159	        if (tid) {
160	          await qc.invalidateQueries({
161	            queryKey: ["beckn", "status", tid],
162	          });
163	        }
164	        return res;
165	      } finally {
166	        setActing(false);
167	      }
168	    },
169	    [qc, transactionId],
170	  );
171	
172	  const reset = useCallback(() => {
173	    setTransactionId(undefined);
174	    setSlices({});
175	    setError(undefined);
176	    setAwaiting(null);
177	  }, []);
178	
179	  // Seed an existing transaction (persisted on a ResourceRequest) so the CC
180	  // console can fire `confirm` and poll a transaction it did not discover.
181	  const resume = useCallback((existingTransactionId: string) => {
182	    setTransactionId(existingTransactionId);
183	    setError(undefined);
184	  }, []);
185	
186	  const catalog: CatalogOption[] = useMemo(
187	    () => extractOffers(slices["on_discover"]),
188	    [slices],
189	  );
190	  const slots: BecknSlot[] = useMemo(
191	    () => extractSlots(slices["on_select"]),
192	    [slices],
193	  );
194	  const initResult: BecknInitResult = useMemo(
195	    () => extractInitResult(slices["on_init"]),
196	    [slices],
197	  );
198	
199	  return {
200	    transactionId,
201	    status,
202	    phase: phaseFor(status),
203	    awaiting,
204	    isTerminal: isTerminalStatus(status),
205	    isPolling: statusQuery.isFetching || sliceQuery.isFetching,
206	    acting,
207	    error,
208	    resourceRequestId: statusQuery.data?.resourceRequestId,
209	    statusRecord: statusQuery.data,
210	    catalog,
211	    slots,
212	    initResult,
213	    slices,
214	    act,
215	    reset,
216	    resume,
217	  };
218	}
219	
220	export type UseBecknTransaction = ReturnType<typeof useBecknTransaction>;
