export const meta = {
  name: 'ccn-wizard-review',
  description: 'Review the CCN console wizard diff across 4 dimensions, adversarially verify findings',
  phases: [
    { title: 'Review', detail: 'four dimensions in parallel' },
    { title: 'Verify', detail: 'adversarial check per finding' },
  ],
}

const FILES = [
  'src/components/Resource/beckn/AppointmentWizard.tsx (new)',
  'src/components/Resource/CcnConsole.tsx (rewritten)',
  'src/hooks/useBecknTransaction.ts (modified)',
  'public/locale/en.json (ccn_ block modified)',
].join('\n')

const CONTEXT = `Repo: /Users/bodhishthomas/code/care_fe (React 19 + TS + Vite EMR frontend).
Uncommitted changes implement a full-screen appointment-booking wizard for the Care-Coordinator (CCN) console over a Beckn protocol flow (discover → on_discover → select → on_select → confirm → on_confirm, driven via useBecknTransaction which POSTs actions and polls a status record until the on_* callback lands).
Changed files:
${FILES}
Run \`git diff\` and \`git status\` in the repo to see the exact changes; read the full files and neighbours (BecknFlow.tsx, ResourceForm.tsx, becknModels.ts) for context.
Design intent: 4-step wizard (Service → Provider → Slot → Review) in a full-screen Dialog; completed steps revisitable; changing provider re-fires select; changing service resets the transaction; review step replaces the old ConfirmDialog; success view + booked banner; collapsible network-activity trail; console list got status-colored badges, counts, relative times, empty states. BecknFlow/ResourceForm (consultation flow) must be UNAFFECTED. Quality bar: polished demo, not production hardening.`

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'number' },
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          detail: { type: 'string', description: 'What is wrong and the concrete failure scenario (inputs/state → wrong outcome)' },
        },
        required: ['title', 'file', 'severity', 'detail'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    isReal: { type: 'boolean' },
    reasoning: { type: 'string' },
    suggestedFix: { type: 'string' },
  },
  required: ['isReal', 'reasoning'],
}

const DIMENSIONS = [
  {
    key: 'state-machine',
    prompt: `${CONTEXT}\n\nDimension: WIZARD STATE MACHINE. Scrutinize AppointmentWizard.tsx only. Trace every path: forward happy path; back-navigation from each step (incl. stepper clicks); changing provider then continuing (re-select) vs unchanged provider; changing service (reset); error at each action (incl. failed POST); retry; start over; close/abandon guard (Esc, X, backdrop); reopen after success; reopen after abandon; the phase→step effect interacting with back-nav; busy gating. Find states where the UI shows the wrong step, stale data, dead-ends, or where a button fires with stale/undefined inputs (e.g. slot undefined at confirm). Report only defects with a concrete reproduction path.`,
  },
  {
    key: 'hook-races',
    prompt: `${CONTEXT}\n\nDimension: HOOK & REACT-QUERY RACES. Scrutinize the useBecknTransaction.ts diff (STALE_SLICES clearing, last-write-wins slice cache, removeQueries on re-fire, catch on failed POST) plus how AppointmentWizard consumes it. Hunt for: stale on_select slots shown after provider change; removeQueries vs in-flight observers; the slice query refetch lifecycle when status flips (enabled gating via sliceActionFor); awaiting never clearing; the catch path returning a fake result and what callers do with it; polling that never stops; effects re-running with stale closures. Also confirm the changes do NOT break BecknFlow.tsx / ResourceForm.tsx consultation flow (init path, resume, ConfirmDialog). Report only defects with a concrete failure scenario.`,
  },
  {
    key: 'integration',
    prompt: `${CONTEXT}\n\nDimension: INTEGRATION & REGRESSIONS. Check CcnConsole.tsx rewrite against its route usage (find where CcnConsole is routed), the removed AppointmentBooking/Select code, BookingLauncher/wizard wiring (patient built via becknPatientFrom, onBooked, open state), tab counts, list rows (fields exist on ResourceRequestListRead), badge variants exist on the Badge component, icon names exist in UniconPaths.json, and i18n: every t() key used in the two components exists in public/locale/en.json, and the keys I removed (ccn_no_incoming_requests, ccn_no_outgoing_requests, ccn_select_service_type) have zero remaining usages anywhere (grep the whole repo incl. tests). Report only actual breakages.`,
  },
  {
    key: 'ux-conventions',
    prompt: `${CONTEXT}\n\nDimension: UX POLISH & CODE CONVENTIONS. Review AppointmentWizard.tsx and CcnConsole.tsx as a picky staff frontend engineer: full-screen DialogContent override correctness (the base dialog classes it must beat: fixed top-[50%] left-[50%] translate, grid, max-w, p-6 — check tailwind-merge actually resolves each conflict, and the built-in absolute close button placement vs the header patient chip mr-8), scroll behavior of the step body, keyboard/focus basics, dark-mode classes (the repo's dialog has dark: variants — do the new components break badly in dark mode?), truncation on long provider/patient names, empty-catalog dead-end (no providers returned → is there a way forward?), and repo conventions (i18n for all user-facing strings, double quotes, named exports pattern, comment style). Report concrete defects only, not nitpicks a demo wouldn't notice.`,
  },
]

const results = await pipeline(
  DIMENSIONS,
  (d) => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  (review, d) => {
    const findings = (review?.findings ?? []).filter((f) => f.severity !== 'minor' || /dead.?end|stale|wrong step|missing key/i.test(f.title + f.detail))
    if (findings.length === 0) return []
    return parallel(findings.map((f) => () =>
      agent(
        `${CONTEXT}\n\nAdversarially verify this ${d.key} review finding. Read the actual current code (it may differ from the reviewer's assumption) and try to REFUTE it. It is only real if the stated failure scenario actually occurs in the current code. Default to isReal=false when uncertain or when the impact is imperceptible in a demo.\n\nFinding: ${f.title}\nFile: ${f.file}${f.line ? ` line ~${f.line}` : ''}\nSeverity: ${f.severity}\nDetail: ${f.detail}`,
        { label: `verify:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT_SCHEMA },
      ).then((v) => ({ ...f, dimension: d.key, verdict: v }))
    ))
  },
)

const confirmed = results
  .filter(Boolean)
  .flat()
  .filter(Boolean)
  .filter((f) => f.verdict?.isReal)

log(`${confirmed.length} confirmed finding(s)`)
return { confirmed }

